  // Original args.
  const args = { ...input };

  // Resolve default values.
  if (!accounts.player.value) {
    accounts.player.value = await findPlayerPda({
      payer: expectAddress(accounts.payer.value),
    });
  }
  if (!accounts.quest.value) {
    accounts.quest.value = await findQuestPda({
      questId: expectSome(args.questId),
    });
  }
  if (!accounts.questCompletion.value) {
    accounts.questCompletion.value = await findQuestCompletionPda({
      quest: expectAddress(accounts.quest.value),
      payer: expectAddress(accounts.payer.value),
    });
  }
  if (!accounts.systemProgram.value) {
    accounts.systemProgram.value =
      "11111111111111111111111111111111" as Address<"11111111111111111111111111111111">;
  }

  const getAccountMeta = getAccountMetaFactory(programAddress, "programId");
  return Object.freeze({
    accounts: [
      getAccountMeta(accounts.payer),
      getAccountMeta(accounts.player),
      getAccountMeta(accounts.quest),
      getAccountMeta(accounts.questCompletion),
      getAccountMeta(accounts.systemProgram),
    ],
    data: getCompleteQuestInstructionDataEncoder().encode(
      args as CompleteQuestInstructionDataArgs,
    ),
    programAddress,
  } as CompleteQuestInstruction<
    TProgramAddress,
    TAccountPayer,
    TAccountPlayer,
    TAccountQuest,
    TAccountQuestCompletion,
    TAccountSystemProgram
  >);
